out={}
items=list(FULL.items())
B=10
for i in range(0,len(items),B):
    batch=items[i:i+B]
    variants=[]
    for k,full in batch:
        parts=full.split()
        variants.append((k,full))
        if len(parts)==3: variants.append((k,f'{parts[2]}, {parts[0]} {parts[1]}')); variants.append((k,f'{parts[2]} {parts[0]}'))
    vals=' '.join(f'("{k}" "{v}")' for k,v in variants)
    q='''SELECT ?key ?item ?itemLabel ?desc ?img ?birth ?ruwiki WHERE {
  VALUES (?key ?name) { %s }
  SERVICE wikibase:mwapi { bd:serviceParam wikibase:endpoint "www.wikidata.org"; wikibase:api "EntitySearch"; mwapi:search ?name; mwapi:language "ru"; mwapi:limit "5". ?item wikibase:apiOutputItem mwapi:item. }
  ?item wdt:P31 wd:Q5.
  OPTIONAL { ?item wdt:P18 ?img } OPTIONAL { ?item wdt:P569 ?birth }
  OPTIONAL { ?item schema:description ?desc FILTER(LANG(?desc)="ru") }
  OPTIONAL { ?ruwiki schema:about ?item; schema:isPartOf <https://ru.wikipedia.org/> }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "ru,en". } }'''%vals
    d=None
    for attempt in range(4):
        r=subprocess.run(['curl','-sS','-m','180','-A',UA,'--get','https://query.wikidata.org/sparql','--data-urlencode','query='+q,'-H','Accept: application/sparql-results+json'],capture_output=True,text=True)
        try: d=json.loads(r.stdout); break
        except Exception: print('retry',i,r.stdout[:150],file=sys.stderr); time.sleep(10*(attempt+1))
    if not d: continue
    for b in d['results']['bindings']:
        g=lambda k: b.get(k,{}).get('value')
        out.setdefault(g('key'),[]).append({'item':g('item'),'label':g('itemLabel'),'desc':g('desc'),'img':g('img'),'birth':(g('birth') or '')[:4],'ruwiki':g('ruwiki')})
    print(i+len(batch),'/',len(items),flush=True); time.sleep(2)
json.dump(out,open('wd2.json','w'),ensure_ascii=False,indent=0)
print('found',len(out))
